local BookbindingPressMaker = {}
local PRODUCTS = {
    simple_wood_bookbinding_press = { name = "Preprosta lesena vezna stiskalnica", woodCost = 4, ironCost = 1, leatherCost = 1, time = 5, cost = 180, science = 22, happiness = 2, description = "Preprosta lesena vezna stiskalnica za vezavo knjig." },
    iron_reinforced_bookbinding = { name = "Železnookrepljena vezna stiskalnica", woodCost = 4, ironCost = 2, leatherCost = 1, time = 8, cost = 440, science = 35, happiness = 2, prestige = 2, description = "Železnookrepljena vezna stiskalnica za trgovce." },
    silver_geared_bookbinding = { name = "Srebrnozobčana vezna stiskalnica", woodCost = 4, silverCost = 1, ironCost = 2, leatherCost = 1, time = 12, cost = 1000, science = 50, happiness = 3, prestige = 6, description = "Srebrnozobčana vezna stiskalnica za plemiče." },
    gold_trimmed_bookbinding = { name = "Zlatookrasna vezna stiskalnica", woodCost = 4, goldCost = 1, silverCost = 1, ironCost = 2, leatherCost = 1, time = 16, cost = 2300, science = 65, happiness = 4, prestige = 14, description = "Zlatookrasna vezna stiskalnica za visoke plemiče." },
    jewel_set_bookbinding = { name = "Draguljasta vezna stiskalnica", woodCost = 4, goldCost = 1, silverCost = 1, ironCost = 2, leatherCost = 1, jewelCost = 1, time = 20, cost = 5000, science = 80, happiness = 6, prestige = 27, description = "Vezna stiskalnica z draguljem za visoko plemstvo." },
    royal_grand_bookbinding = { name = "Kraljevski veliki vezna stiskalnica", woodCost = 6, goldCost = 2, silverCost = 2, ironCost = 2, leatherCost = 1, jewelCost = 2, pearlCost = 2, time = 27, cost = 11000, science = 95, happiness = 12, prestige = 58, description = "Velika kraljevska vezna stiskalnica z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    bookbinding_workshop = { name = "Vezna delavnica", cost = { gold = 290, wood = 160, stone = 140, iron = 6, leather = 4 }, upkeep = 6, qualityBonus = 5 },
    printing_loft = { name = "Tiskarska podstrešje", cost = { gold = 1050, wood = 320, stone = 280, silver = 6, iron = 6 }, upkeep = 24, qualityBonus = 18 },
    master_bookbinding_atelier = { name = "Mojstrski vezni atelje", cost = { gold = 2850, wood = 380, stone = 520, silver = 32, gold = 6 }, upkeep = 66, qualityBonus = 30 },
    royal_printing_palace = { name = "Kraljevska tiskarska palača", cost = { gold = 12200, wood = 600, stone = 780, gold = 78, jewel = 18 }, upkeep = 245, qualityBonus = 55, prestigeBonus = 50 },
}
BookbindingPressMaker.woodStock = 20; BookbindingPressMaker.ironStock = 12; BookbindingPressMaker.leatherStock = 10; BookbindingPressMaker.silverStock = 6; BookbindingPressMaker.goldStock = 6; BookbindingPressMaker.jewelStock = 4; BookbindingPressMaker.pearlStock = 4
BookbindingPressMaker.productStock = {}; BookbindingPressMaker.buildings = {}; BookbindingPressMaker.maker = nil; BookbindingPressMaker.activeMaking = {}; BookbindingPressMaker.totalProducts = 0; BookbindingPressMaker.dayTimer = 0
function BookbindingPressMaker.init() BookbindingPressMaker.woodStock=20; BookbindingPressMaker.ironStock=12; BookbindingPressMaker.leatherStock=10; BookbindingPressMaker.silverStock=6; BookbindingPressMaker.goldStock=6; BookbindingPressMaker.jewelStock=4; BookbindingPressMaker.pearlStock=4; BookbindingPressMaker.productStock={}; BookbindingPressMaker.buildings={}; BookbindingPressMaker.maker=nil; BookbindingPressMaker.activeMaking={}; BookbindingPressMaker.totalProducts=0; BookbindingPressMaker.dayTimer=0; print("[BookbindingPressMaker] Royal Bookbinding Press Maker System initialized (6 products, 4 buildings)") end
function BookbindingPressMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BookbindingPressMaker.maker={name=n or ("Vezar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vezar najet: %s (spretnost: %d)",BookbindingPressMaker.maker.name,s),"success") end; return true end
function BookbindingPressMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BookbindingPressMaker.build(id) local ok,e=BookbindingPressMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BookbindingPressMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function BookbindingPressMaker.getQualityBonus() local b=0; for _,bd in ipairs(BookbindingPressMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function BookbindingPressMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and BookbindingPressMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.ironCost and BookbindingPressMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.leatherCost and BookbindingPressMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and BookbindingPressMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and BookbindingPressMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and BookbindingPressMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and BookbindingPressMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #BookbindingPressMaker.buildings==0 then return false,"Potrebna vezna delavnica" end; if not BookbindingPressMaker.maker then return false,"Potreben vezar" end; return true end
function BookbindingPressMaker.make(pt,qty) qty=qty or 1; local ok,e=BookbindingPressMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then BookbindingPressMaker.woodStock=BookbindingPressMaker.woodStock-d.woodCost*qty end; if d.ironCost then BookbindingPressMaker.ironStock=BookbindingPressMaker.ironStock-d.ironCost*qty end; if d.leatherCost then BookbindingPressMaker.leatherStock=BookbindingPressMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then BookbindingPressMaker.silverStock=BookbindingPressMaker.silverStock-d.silverCost*qty end; if d.goldCost then BookbindingPressMaker.goldStock=BookbindingPressMaker.goldStock-d.goldCost*qty end; if d.jewelCost then BookbindingPressMaker.jewelStock=BookbindingPressMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then BookbindingPressMaker.pearlStock=BookbindingPressMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if BookbindingPressMaker.maker then t=math.max(1,t-math.floor(BookbindingPressMaker.maker.skill/13)) end; table.insert(BookbindingPressMaker.activeMaking,{id="bookbindingpress_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,science=d.science or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Gradnja: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function BookbindingPressMaker.completeMaking(m) local q=1.0+(BookbindingPressMaker.getQualityBonus()/100); if BookbindingPressMaker.maker then q=q+(BookbindingPressMaker.maker.skill/140) end; q=math.min(2.5,q); BookbindingPressMaker.productStock[m.productType]=(BookbindingPressMaker.productStock[m.productType] or 0)+m.quantity; BookbindingPressMaker.totalProducts=BookbindingPressMaker.totalProducts+m.quantity; if m.science>0 and _G.state then _G.state.science=(_G.state.science or 0)+m.science end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BookbindingPressMaker.maker then BookbindingPressMaker.maker.itemsMade=BookbindingPressMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then BookbindingPressMaker.maker.skill=math.min(100,BookbindingPressMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vezna stiskalnica izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"bookbindingpress.completed",{productName=m.productName,science=m.science,prestige=m.prestige,happiness=m.happiness}) end end
function BookbindingPressMaker.update(dt) if not _G.state then return end; BookbindingPressMaker.dayTimer=BookbindingPressMaker.dayTimer+dt; if BookbindingPressMaker.dayTimer>=30 then BookbindingPressMaker.dayTimer=0; for i=#BookbindingPressMaker.activeMaking,1,-1 do local m=BookbindingPressMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BookbindingPressMaker.completeMaking(m); table.remove(BookbindingPressMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BookbindingPressMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BookbindingPressMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function BookbindingPressMaker.getStats() return {woodStock=BookbindingPressMaker.woodStock,ironStock=BookbindingPressMaker.ironStock,leatherStock=BookbindingPressMaker.leatherStock,silverStock=BookbindingPressMaker.silverStock,goldStock=BookbindingPressMaker.goldStock,jewelStock=BookbindingPressMaker.jewelStock,pearlStock=BookbindingPressMaker.pearlStock,productStock=BookbindingPressMaker.productStock,numBuildings=#BookbindingPressMaker.buildings,hasMaker=BookbindingPressMaker.maker~=nil,makerName=BookbindingPressMaker.maker and BookbindingPressMaker.maker.name or "—",makerSkill=BookbindingPressMaker.maker and BookbindingPressMaker.maker.skill or 0,activeMaking=#BookbindingPressMaker.activeMaking,totalProducts=BookbindingPressMaker.totalProducts} end
return BookbindingPressMaker
